+interface DurationUnit {
+  suffix: string;
+  seconds: number;
 }

+/** Largest first; a formatter starts at its `largestUnit` and works down. */
+const DURATION_UNITS: readonly DurationUnit[] = [
+  { suffix: "d", seconds: 86_400 },
+  { suffix: "h", seconds: 3_600 },
+  { suffix: "m", seconds: 60 },
+  { suffix: "s", seconds: 1 },
+];
+
+export type DurationUnitName = "d" | "h" | "m" | "s";
+
+export interface DurationFormatOptions {
+  /** Largest unit that may appear. Leading zero units are omitted. */
+  largestUnit?: DurationUnitName;
+  /** Text placed between parts. */
+  separator?: string;
+  /** Show the seconds part even when it is zero and other parts are present. */
+  alwaysSeconds?: boolean;
+}
+
+export function createDurationFormatter(options: DurationFormatOptions = {}): (ms: number) => string {
+  const { largestUnit = "h", separator = " ", alwaysSeconds = true } = options;
+  const start = DURATION_UNITS.findIndex((u) => u.suffix === largestUnit);
+  const units = DURATION_UNITS.slice(start);
+  return (ms) => {
+    let remaining = Math.round(ms / 1000);
+    const parts: string[] = [];
+    for (const unit of units) {
+      const count = Math.floor(remaining / unit.seconds);
+      remaining -= count * unit.seconds;
+      const isSeconds = unit.seconds === 1;
+      const show = count > 0 || (parts.length > 0 && (!isSeconds || alwaysSeconds)) || (isSeconds && parts.length === 0);
+      if (show) {
+        parts.push(`${count}${unit.suffix}`);
+      }
+    }
+    return parts.join(separator);
+  };
+}
+
+export const formatDuration = createDurationFormatter();
+
 function pad2(n: number): string {
   return n < 10 ? `0${n}` : String(n);
 }

 export function formatDate(d: Date): string {
   return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
